layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); border-left: 3px solid rgb(189, 189, 189); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 17px; font-weight: 400; font-style: italic; line-height: 1.588; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 20px; padding-right: 20px; padding-bottom: 20px; padding-left: 20px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: rgb(117, 117, 117); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="hero"] h1 { color: var(--ryt-accent); font-family: var(--ryt-font-heading); font-size: 44px; font-weight: 300; font-style: normal; line-height: 1.1; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: #858585; border-bottom: 1px solid var(--ryt-bg); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 40px; font-weight: 100; font-style: normal; line-height: 1.1; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="header"] { background-image: url("{{assets}}/hugo-theme-hamburg_aa6ce2a340d5/bg.jpg"); background-size: cover; background-position: 50% 50%; background-repeat: repeat }
[data-ryt="nav"] a { background-color: rgba(0, 0, 0, 0.125); border-top: 1px solid var(--ryt-bg); border-right: 1px solid var(--ryt-bg); border-bottom: 1px solid var(--ryt-bg); border-left: 1px solid var(--ryt-bg); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 13px; font-weight: 400; font-style: normal; line-height: 1.588; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 6px; padding-right: 12px; padding-bottom: 6px; padding-left: 12px; transition: all; color: var(--ryt-text) }
[data-ryt="button"] { color: var(--ryt-bg); background-color: rgba(0, 0, 0, 0.125); border-top: 1px solid var(--ryt-bg); border-right: 1px solid var(--ryt-bg); border-bottom: 1px solid var(--ryt-bg); border-left: 1px solid var(--ryt-bg); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; line-height: 1.588; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 6px; padding-right: 12px; padding-bottom: 6px; padding-left: 12px; transition: all }
[data-ryt="review"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 17px; font-weight: 400; font-style: normal; line-height: 1.588; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="cover"] { border-top: 1px solid rgb(220, 237, 200); border-right: 1px solid rgb(220, 237, 200); border-bottom: 1px solid rgb(220, 237, 200); border-left: 1px solid rgb(220, 237, 200); border-radius: 0px }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 300; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 34px; font-weight: 300; font-style: normal; line-height: 1.1; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: var(--ryt-accent) }
[data-ryt="cover"]:hover { border-top-width: 1px; border-right-width: 1px; border-bottom-width: 1px; border-left-width: 1px; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-color: rgb(156, 204, 101); border-right-color: rgb(156, 204, 101); border-bottom-color: rgb(156, 204, 101); border-left-color: rgb(156, 204, 101) }
[data-ryt="button"]:hover { background-color: rgba(189, 189, 189, 0.3); background-color: rgba(189, 189, 189, 0.125); color: var(--ryt-accent); color: var(--ryt-bg); background-color: rgba(189, 189, 189, 0.3); border-top-color: var(--ryt-bg); border-right-color: var(--ryt-bg); border-bottom-color: var(--ryt-bg); border-left-color: var(--ryt-bg) }
[data-ryt="nav"] a:hover { background-color: rgba(189, 189, 189, 0.3); background-color: rgba(189, 189, 189, 0.125); color: var(--ryt-accent); background-color: rgba(189, 189, 189, 0.3); border-top-color: var(--ryt-bg); border-right-color: var(--ryt-bg); border-bottom-color: var(--ryt-bg); border-left-color: var(--ryt-bg) }
[data-ryt="brand"]:hover { color: var(--ryt-accent) }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: var(--ryt-accent) }
